-- ============================================================
-- 京菓子（テーマID: 23, category_id: 3）問題投入SQL
-- 全20問（難易度1〜3）
-- 選択肢対応: (ア)=0, (イ)=1, (ウ)=2, (エ)=3
-- ============================================================

INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES

(3, 23, '京都を代表する焼き菓子「八ツ橋（やつはし）」の名前の由来として有力な説はどれか。', '橋を8本渡ったところにある茶屋が始め', '江戸時代の音楽家・八橋検校（やつはしけんぎょう）に由来', '8枚の餅を橋のように並べた形から', '京都の八条通で始まった菓子から', 1, '八ツ橋の名前の由来として有力なのは、江戸時代の盲目の箏曲家・八橋検校（1614〜1685年）の墓参者に売られた菓子が始まりという説です。検校の名と菓子の形（箏に似た反り）が結びついています。', 1, false),
(3, 23, '「生八ツ橋（なまやつはし）」の基本的な材料として正しいのはどれか。', '米粉・砂糖・ニッキ（シナモン）', '小麦粉・バター・砂糖', '白玉粉・餡・抹茶', 'そば粉・砂糖・塩', 0, '生八ツ橋の生地は米粉（うるち米粉）・砂糖・ニッキ（シナモン）を主な材料とし、蒸した後に薄く伸ばして作ります。ニッキの香りが特徴で、三角に折ってあんこを包んだ生八ツ橋が最も一般的です。', 1, false),
(3, 23, '「阿闍梨餅（あじゃりもち）」を作っている京都の老舗菓子店はどれか。', '鶴屋吉信', '笹屋伊織', '亀屋良長', '満月', 3, '阿闍梨餅は「満月（まんげつ）」が製造する半生菓子で、餅粉を使った外皮に丹波大納言小豆の餡を包んだ人気の京菓子です。弾力のある食感が特徴で、お土産として広く親しまれています。', 1, false),
(3, 23, '「笹屋伊織（ささやいおり）」の最も有名な銘菓で、棹状の外郎（ういろう）に餡が入った菓子はどれか。', 'どら焼き', '亥の子餅', 'どら焼き（竹の節型）', '法楽焼', 2, '笹屋伊織の代表作「どら焼き」は一般的などら焼きとは全く異なり、竹の筒に流し込んで焼いた棒状の外郎（ういろう）に餡が詰まったもので、毎月20・21日のみ販売される限定品として有名です。', 1, false),
(3, 23, '京都の老舗和菓子屋「鶴屋吉信（つるやよしのぶ）」の代表銘菓はどれか。', '柚餅（ゆうもち）', '柚子山', '柚餅子（ゆうべし）', '柚子饅頭', 0, '鶴屋吉信の代表銘菓は「柚餅（ゆうもち）」で、上品な柚子の香りが特徴の練り切り（ねりきり）菓子です。1803年創業の老舗として知られ、茶の湯のための上生菓子でも有名です。', 2, false),
(3, 23, '「みたらし団子（みたらしだんご）」の発祥の地として知られる神社はどこか。', '八坂神社', '北野天満宮', '下鴨神社', '伏見稲荷大社', 2, 'みたらし団子は下鴨神社（賀茂御祖神社）の境内を流れる「御手洗池（みたらしのいけ）」から湧き出る泡を模して作られたと伝わります。加茂みたらし茶屋が発祥とされ、5本の串（1+4）が特徴的な形です。', 1, false),
(3, 23, '「祇園ちご餅（ぎおんちごもち）」など、祇園祭の時期に売られる縁起物の菓子として有名なものはどれか。', '花びら餅', 'ちまき（粽）', '桜餅', '草餅', 1, '祇園祭の縁起物として、各山鉾町から「粽（ちまき）」が授与されます。これは食べるものではなく玄関に飾る厄除けの粽です。一方「ちご餅」は祇園祭期間中に八坂神社周辺で売られる餅菓子として知られています。', 2, false),
(3, 23, '毎年1月初め（元旦〜1月7日頃）だけ売り出される京都の年始の和菓子「花びら餅（はなびらもち）」の材料として正しいのはどれか。', 'ゴボウ・みそ餡・餅', '桜の葉・餡・餅', '柚子・白餡・求肥', '黒豆・きなこ・餅', 0, '花びら餅（はなびらもち）は薄い餅でゴボウ・みそ餡などを包んだ正月の伝統菓子です。宮中で「菱葩（ひしはなびら）」と呼ばれた正月行事の食べ物が起源で、現在は茶道の初釜でも定番の菓子となっています。', 2, false),
(3, 23, '京都の和菓子文化で「上生菓子（じょうなまがし）」とはどのような菓子か。', '安価な大量生産の和菓子', '茶の湯のために作られた繊細で意匠を凝らした生菓子', '外国人向けに開発された洋風和菓子', '乾燥させて長期保存できる和菓子', 1, '上生菓子は茶の湯（茶道）のために作られた高級生菓子で、季節の花・植物・行事などをモチーフに練り切り・求肥などで精巧に作られます。見た目の美しさと季節感が最大の特徴で、和菓子の最高峰とされています。', 1, false),
(3, 23, '「練り切り（ねりきり）」の主な材料として正しいのはどれか。', '小麦粉・バター・卵', '白餡・白玉粉（求肥）', '寒天・餡・砂糖', '米粉・砂糖・塩', 1, '練り切り（ねりきり）は白餡に求肥（ぎゅうひ）などを混ぜてなめらかに練り上げた生地で形を作る上生菓子です。柔らかく細工しやすいため、花・動物・季節のモチーフを精巧に表現できます。', 2, false),
(3, 23, '「虎屋（とらや）」は室町時代末期に創業した老舗和菓子屋だが、その本拠はどこにあったか。', '大阪', '江戸（東京）', '奈良', '京都御所付近', 3, '虎屋は室町時代末期（16世紀）に京都御所近くで創業した和菓子の老舗です。宮廷・天皇家に菓子を納めてきた格式ある店で、現在も東京赤坂に本店を構えながら、京都でも営業しています。', 2, false),
(3, 23, '「黒豆（くろまめ）」が京都の正月料理・おせちの代表として使われる意味はどれか。', '黒色が邪気を払う', '「まめに（勤勉に）働く」という縁起に由来', '黒豆が豊作の象徴', '武家社会での儀礼食', 1, '黒豆（特に丹波黒大豆）は「まめに（=勤勉に、健康に）働けるように」という縁起を担って正月のおせちに欠かせない食材です。丹波産の大粒の黒大豆を甘く煮た黒豆は、京都を代表する正月の味として知られています。', 1, false),
(3, 23, '「和三盆（わさんぼん）」とはどのような砂糖か。', '三度精製された高級白砂糖', '黒糖の一種', '人工甘味料の和風名称', 'きびから作った粗糖', 0, '和三盆（わさんぼん）は主に四国（徳島・香川）で生産される高級和菓子用砂糖です。竹糖を「盆（たらい）」で三度研ぐ工程から名付けられた上品な甘みの砂糖で、京都の高級和菓子・落雁などに使われます。', 2, false),
(3, 23, '「聖護院八ツ橋（しょうごいんやつはし）」「本家西尾八ツ橋」など複数の老舗が競合しているが、焼き八ツ橋（硬い八ツ橋）の特徴として正しいのはどれか。', '柔らかくもちもちした食感', '薄く焼き上げた硬い瓦状の食感', '揚げたサクサクの食感', '蒸した半透明の食感', 1, '焼き八ツ橋（硬い八ツ橋）は薄い生地を瓦状に焼いた硬い食感の菓子です。シナモン（ニッキ）の強い香りと硬い食感が特徴で、土産物の定番として古くから親しまれています。', 1, false),
(3, 23, '京都の「落雁（らくがん）」の材料として正しいのはどれか。', '米粉や麦粉・砂糖・水飴などを型に押し固めた乾菓子', '餡を求肥で包んだ半生菓子', '白玉粉を茹でた菓子', 'バター・砂糖を焼いた洋菓子', 0, '落雁（らくがん）は米粉・麦粉などに砂糖・水飴を加えて型で押し固めた乾菓子（干菓子）です。保存が利くため仏事・神事の供物にも広く使われます。京都では御所や茶道関連の上品な落雁が多く作られています。', 2, false),
(3, 23, '京都の菓子処「本家尾張屋（もとやおわりや）」で有名な菓子はどれか。', '八ツ橋', 'そばぼうろ', 'どら焼き', '抹茶ロール', 1, '本家尾張屋は室町時代創業の老舗菓子・そば店で、「そばぼうろ」が代表菓子として知られています。そば粉を使ったサクサクの焼き菓子で、京都土産の定番のひとつです。', 2, false),
(3, 23, '「椿餅（つばきもち）」が日本最古の和菓子のひとつとされる根拠はどれか。', '奈良時代の土器から発見されたから', '源氏物語に登場する菓子として知られているから', '平安時代の宮廷で最初に作られた記録があるから', '鑑真が中国から持ち込んだとされているから', 1, '椿餅（つばきもち）は平安時代の源氏物語（玉鬘の巻）に登場し、「菓子の記録として日本最古」と言われる菓子のひとつです。道明寺粉で作った餅に餡を包み椿の葉で挟んだ菓子で、現在も再現・販売されています。', 3, false),
(3, 23, '茶道で茶を点てる前に提供される「主菓子（おもがし）」の役割はどれか。', '食欲増進のため', '濃茶の苦みを和らげるため', '来客へのあいさつ代わり', '茶の香りを引き立てるため', 1, '主菓子（おもがし）は茶道の茶事で濃茶の前に出される上生菓子で、濃茶の強い苦みを和らげる甘みを提供する役割があります。季節のテーマや亭主の趣向を表現した生菓子が選ばれます。', 1, false),
(3, 23, '「亥の子餅（いのこもち）」が食べられる行事はどれか。', 'お正月', '十月（旧暦）の亥の日の行事', '祇園祭', '節分', 1, '亥の子餅は旧暦10月の亥の日（現代では11月頃）に食べる餅菓子です。猪の子の形をしており、無病息災・子孫繁栄などを祈る亥の子祝いの行事食です。茶人の間では「亥の日」から炉開きを行う習慣があり、亥の子餅が定番の菓子とされています。', 2, false),
(3, 23, '京都の和菓子「宝来（ほうらい）」が有名な菓子司（かしし）はどれか。', '叶匠壽庵', '鍵善良房', '中村軒', '老松', 1, '「鍵善良房（かぎぜんよしふさ）」は祇園に本店を置く老舗和菓子屋で、代表作「くずきり」と「宝来（ほうらい）」で有名です。昆布を菓子に見立てた「宝来」は縁起物の和菓子として知られています。', 3, false);

